\label{lmm:dltii}
The following equivalences hold true, for all hyperteams $\HypAsg \in
\HypAsgSet$ and property $\PsiSet \subseteq \AsgSet$.
\begin{enumerate}[1)]
  \item\label{lmm:dltii(ea)}
    Statements~\ref{lmm:dltii(ea:org)} and~\ref{lmm:dltii(ea:dlt)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:dltii(ea:org)}
        there exists a team $\TeamAsg \in \HypAsg$ (\resp, $\TeamAsg \in
        \dual{\HypAsg}$) such that $\TeamAsg \subseteq \PsiSet$;
      \item\label{lmm:dltii(ea:dlt)}
        for all teams $\TeamAsg' \in \dual{\HypAsg}$ (\resp, $\TeamAsg' \in
        \HypAsg$), it holds that $\TeamAsg' \cap \PsiSet \neq \emptyset$.
    \end{enumerate}
  \item\label{lmm:dltii(ee)}
    Statements~\ref{lmm:dltii(ee:org)} and~\ref{lmm:dltii(ee:dlt)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:dltii(ee:org)}
        there exists a team $\TeamAsg \in \HypAsg$ such that $\TeamAsg \cap
        \PsiSet \neq \emptyset$;
      \item\label{lmm:dltii(ee:dlt)}
        there exists a team $\TeamAsg' \in \dual{\HypAsg}$ such that
        $\TeamAsg' \cap \PsiSet \neq \emptyset$.
    \end{enumerate}
  \item\label{lmm:dltii(aa)}
    Statements~\ref{lmm:dltii(aa:org)} and~\ref{lmm:dltii(aa:dlt)} are
