Assume that the two players of $\HypAsg$, defined over the variables $\{
\varElm, \yvarElm \}$, are interpreted according to the alternation flag $\QAE$:
Abelard chooses the team and Eloise chooses the assignment in the team.

\label{def:sem(adif)}
The \emph{Hodges' alternating semantic relation} ${\AStr, \HypAsg
\cmodels[][\alpha] \varphiFrm}$ for \ADIF is inductively defined as follows,
for all \ADIF formulae $\varphiFrm$, hyperteams $\HypAsg \in
\HypAsgSet[\subseteq](\sup{\varphiFrm})$, and alternation flags $\alpha \in \{
\QEA, \QAE \}$:
\begin{enumerate}[1)]
  \item\label{def:sem(adif:fbv)}
    \begin{inparaenum}[a)]
      \item\label{def:sem(adif:fbv:ea)}
        $\AStr, \HypAsg \cmodels[][\QEA] \Ff$ if $\emptyset \in \HypAsg$;
      \hfill
      \item\label{def:sem(adif:fbv:ae)}
        $\AStr, \HypAsg \cmodels[][\QAE] \Ff$ if $\HypAsg = \emptyset$;
    \end{inparaenum}
  \item\label{def:sem(adif:tbv)}
    \begin{inparaenum}[a)]
      \item\label{def:sem(adif:tbv:ae)}
        $\AStr, \HypAsg \cmodels[][\QAE] \Tt$ if $\emptyset \not\in
        \HypAsg$;
      \hfill
      \item\label{def:sem(adif:tbv:ea)}
        $\AStr, \HypAsg \cmodels[][\QEA] \Tt$ if $\HypAsg \neq \emptyset$;
    \end{inparaenum}
  \item\label{def:sem(adif:rel)}
    \begin{enumerate}[a)]
      \item\label{def:sem(adif:rel:ea)}
        $\AStr, \HypAsg \cmodels[][\QEA] \RRel(\xVec)$ if there exists a team
        $\TeamAsg \in \HypAsg$ such that, for all assignments $\asgElm \in
        \TeamAsg$, it holds that $\xVec[][\asgElm] \in \RRel[][\AStr]$;
      \item\label{def:sem(adif:rel:ae)}
        $\AStr, \HypAsg \cmodels[][\QAE] \RRel(\xVec)$ if, for all teams
        $\TeamAsg \in \HypAsg$, there exists an assignment $\asgElm \in
        \TeamAsg$ such that $\xVec[][\asgElm] \in \RRel[][\AStr]$;
    \end{enumerate}
  \item\label{def:sem(adif:neg)}
    $\AStr, \HypAsg \cmodels[][\alpha] \neg \phiFrm$ if $\AStr, \HypAsg
    \notcmodels[][\dual{\alpha}] \phiFrm$;
  \item\label{def:sem(adif:con)}
    \begin{enumerate}[a)]
      \item\label{def:sem(adif:con:ea)}
        $\AStr, \HypAsg \cmodels[][\QEA] \phiFrm[1] \LCon \phiFrm[2]$ if, for
        all bipartitions $(\HypAsg[1], \HypAsg[2]) \in \parFun{\HypAsg}$, it
        holds that $\AStr, \HypAsg[1] \cmodels[][\QEA] \phiFrm[1]$ or $\AStr,
        \HypAsg[2] \cmodels[][\QEA] \phiFrm[2]$;
      \item\label{def:sem(adif:con:ae)}
        $\AStr, \HypAsg \cmodels[][\QAE] \phiFrm[1] \LCon \phiFrm[2]$ if
        $\AStr, \dual{\HypAsg} \cmodels[][\QEA] \phiFrm[1] \LCon \phiFrm[2]$;
    \end{enumerate}
  \item\label{def:sem(adif:dis)}
    \begin{enumerate}[a)]
      \item\label{def:sem(adif:dis:ea)}
        $\AStr, \HypAsg \cmodels[][\QEA] \phiFrm[1] \LDis \phiFrm[2]$ if
        $\AStr, \dual{\HypAsg} \cmodels[][\QAE] \phiFrm[1] \LDis \phiFrm[2]$;
      \item\label{def:sem(adif:dis:ae)}
        $\AStr, \HypAsg \cmodels[][\QAE] \phiFrm[1] \LDis \phiFrm[2]$ if there
        exists a bipartition $(\HypAsg[1], \HypAsg[2]) \in
        \parFun{\HypAsg}$ such that $\AStr, \HypAsg[1] \cmodels[][\QAE]
        \phiFrm[1]$ and $\AStr, \HypAsg[2] \cmodels[][\QAE] \phiFrm[2]$;
    \end{enumerate}
  \item\label{def:sem(adif:exs)}
    \begin{enumerate}[a)]
      \item\label{def:sem(adif:exs:ea)}
        $\AStr, \HypAsg \cmodels[][\QEA] \LExs[][_{\pm\WSet}] \varElm \ldotp
        \phiFrm$ if $\AStr, \extFun[\denot{\pm\WSet}]{\HypAsg, \varElm}
        \cmodels[][\QEA] \phiFrm$;
      \item\label{def:sem(adif:exs:ae)}
        $\AStr, \HypAsg \cmodels[][\QAE] \LExs[][_{\pm\WSet}] \varElm \ldotp
        \phiFrm$ if $\AStr, \dual{\HypAsg} \cmodels[][\QEA]
        \LExs[][_{\pm\WSet}] \varElm \ldotp \phiFrm$;
    \end{enumerate}
  \item\label{def:sem(adif:all)}
    \begin{enumerate}[a)]
      \item\label{def:sem(adif:all:ea)}
        $\AStr, \HypAsg \cmodels[][\QEA] \LAll[][_{\pm\WSet}] \varElm \ldotp
        \phiFrm$ if $\AStr, \dual{\HypAsg} \cmodels[][\QAE]
        \LAll[][_{\pm\WSet}] \varElm \ldotp \phiFrm$;
      \item\label{def:sem(adif:all:ae)}
        $\AStr, \HypAsg \cmodels[][\QAE] \LAll[][_{\pm\WSet}] \varElm \ldotp
        \phiFrm$ if $\AStr, \extFun[\denot{\pm\WSet}]{\HypAsg, \varElm}
        \cmodels[][\QAE] \phiFrm$.
    \end{enumerate}
\end{enumerate}

\label{exm:psdsnt}
Consider the pseudo sentence $\varphiSnt[6] = \LExs \varElm \ldotp
\LAll[][-\varElm]  \yvarElm \ldotp \LNeg \psiFrm(\varElm, \yvarElm)$ from
above, where again we instantiate $\psiFrm(\varElm, \yvarElm)$
as $(\varElm = \yvarElm)$.
The exact same reasoning followed in Example~\ref{exm:snt} shows that
$\varphiSnt[6]$ is true in $\AStr$ against the trivial hyperteam $\{\!\{\emptyfun\}\!\}$.
Consequently, the pseudo sentence $\varphiSnt[5] = \LAll \varElm \ldotp
\LExs[][-\varElm] \yvarElm \ldotp \psiFrm(\varElm, \yvarElm)$ is false in
$\AStr$ against $\{\!\{\emptyfun\}\!\}$, being equivalent to the negation of
$\varphiSnt[6]$.

These two pseudo sentences, however, are not equivalent to the sentences
$\varphiSnt[4]$ and $\varphiSnt[3]$, respectively.
To see this, let us evaluate $\varphiSnt[5]$ in $\AStr$ against the hyperteam
$\HypAsg = \{\!\{ \zvarElm\!:\!0, \zvarElm\!:\!1 \}\!\}$ \wrt the alternation
flag $\alpha = \QAE$.
Note that $\zvarElm \in \free{\varphiSnt[5]} = \denot{-\varElm} = \VarSet
\setminus \{ \varElm \}$.
The semantic rule for $\LAll \varElm$ requires to compute the extension
$\extFun[\emptyset]{\HypAsg, \varElm}$ of $\HypAsg$.
This results in
\[
  \AStr, \HypAsg \cmodels[][\QAE] \LAll \varElm \ldotp \LExs[][-\varElm]
  \yvarElm \ldotp (\varElm = \yvarElm)
\ \ \iff\ \
  \AStr, \extFun[\emptyset]{\HypAsg, \varElm} \cmodels[][\QAE]
  \LExs[][-\varElm] \yvarElm \ldotp (\varElm = \yvarElm),
\]
where
$\extFun[\emptyset]{\HypAsg, \varElm} =
\left\{\hspace{-0.35em}\left\{\!\!\!
\begin{array}{cc}
  {\zvarElm}\!:\!0 \\
  {\varElm}\!:\!0
\end{array}
\!\!,\!\!\!
\begin{array}{cc}
  {\zvarElm}\!:\!1 \\
  {\varElm}\!:\!0
\end{array}
\!\!\!\right\}\!,\!\left\{\!\!\!
\begin{array}{c}
  {\zvarElm}\!:\!0\\
  {\varElm}\!:\!1
\end{array}
\!\!,\!\!\!
\begin{array}{c}
  {\zvarElm}\!:\!1\\
  {\varElm}\!:\!1
\end{array}
\!\!\!\right\}\hspace{-0.35em}\right\}$.
The rule for $\LExs[][-\varElm] \yvarElm$ requires to dualise the hyperteam
and switch the flag to $\QEA$.
Since both teams in $\extFun[\emptyset]{\HypAsg, \varElm}$ contains two
assignments, there are four choice functions in total, leading to
\[
  \AStr, \extFun[\emptyset]{\HypAsg, \varElm} \cmodels[][\QAE]
  \LExs[][-\varElm] \yvarElm \ldotp (\varElm = \yvarElm)
\ \ \iff\ \
  \AStr, \dual{\extFun[\emptyset]{\HypAsg, \varElm}} \cmodels[][\QEA]
  \LExs[][-\varElm] \yvarElm \ldotp (\varElm = \yvarElm),
\text{where}
\]
\[
\dual{\extFun[\emptyset]{\HypAsg, \varElm}} =
\left\{\hspace{-0.35em}
\begin{array}{c}
  {\TeamAsg[1]} = \\
  \left\{\hspace{-0.35em}
  \begin{array}{cc}
    {\zvarElm}\!:\!0 \\
    {\varElm}\!:\!0
  \end{array}
