    {\yvarElm}\!:\!1
  \end{array}
  \hspace{-0.35em}\right\}
\end{array}
\!\!,\!\!\!
\begin{array}{c}
  {\TeamAsg[4]} = \\
  \left\{\hspace{-0.35em}
  \begin{array}{cc}
    {\varElm}\!:\!1 \\
    {\yvarElm}\!:\!0
  \end{array}
  \!\!,\!\!\!
  \begin{array}{c}
    {\varElm}\!:\!1\\
    {\yvarElm}\!:\!1
  \end{array}
  \hspace{-0.35em}\right\}
\end{array}
\!\!\right\}\!.
\]
The extension $\der{\HypAsg} \defeq \extFun[\{ \varElm \}]{
\dual{\extFun[\emptyset]{\dual{\HypAsg}, \yvarElm}}, \zvarElm}$ can only use
functions that depend on $\varElm$ alone and there are four of them.
Similarly to the previous example, the hyperteam $\der{\HypAsg}$ ends up
containing $12$ teams.
Among these teams one can find $\XSet \defeq \extFun{\XSet[2], \FFun,
\zvarElm} = \{ \asgElm[1], \asgElm[2] \}$, where $\asgElm[1](\varElm) =
\asgElm[1](\yvarElm) = \asgElm[1](\zvarElm) = 0$, $\asgElm[2](\varElm) =
\asgElm[2](\yvarElm) = \asgElm[2](\zvarElm) = 1$, and $\FFun(\asgElm) =
\asgElm(\varElm)$.
Now, the final step requires checking whether $\AStr, \der{\HypAsg}
\cmodels[][\QEA] (\varElm = \yvarElm) \LCon (\yvarElm = \zvarElm)$.
By the rule for the conjunction connective, this is true if $\AStr,
\der{\HypAsg}[1] \cmodels[][\QEA] (\varElm = \yvarElm)$ or $\AStr,
\der{\HypAsg}[2] \cmodels[][\QEA] (\yvarElm = \zvarElm)$, for all
bipartitions $(\der{\HypAsg}[1], \der{\HypAsg}[2]) \in
\parFun{\hat{\HypAsg}}$.
Obviously, any such partition would contain $\XSet$ either in
$\der{\HypAsg}[1]$ or in $\der{\HypAsg}[2]$.
Since every assignment in $\XSet$ satisfies both $(\varElm = \yvarElm)$ and
$(\yvarElm = \zvarElm)$, the sentence is proved true in $\AStr$ against
$\{\!\{\emptyfun\}\!\}$.

