\label{lmm:empnulhyp}
The following hold true for every \ADIF formula $\varphiFrm$ and hyperteam
$\HypAsg \in \HypAsgSet[\subseteq](\sup{\varphiFrm})$:
\begin{enumerate}[1)]
  \item\label{lmm:empnulhyp(ea)}
    \begin{inparaenum}[a)]
      \item\label{lmm:empnulhyp(ea:emp)}
        $\AStr, \emptyset \notcmodels[][\QEA] \varphiFrm$;
      \hfill
      \item\label{lmm:empnulhyp(ea:nul)}
        $\AStr, \HypAsg \cmodels[][\QEA] \varphiFrm$, where $\emptyset \in
        \HypAsg$;
    \end{inparaenum}
  \item\label{lmm:empnulhyp(ae)}
    \begin{inparaenum}[a)]
      \item\label{lmm:empnulhyp(ae:emp)}
        $\AStr, \emptyset \cmodels[][\QAE] \varphiFrm$;
      \hfill
      \item\label{lmm:empnulhyp(ae:nul)}
        $\AStr, \HypAsg \notcmodels[][\QAE] \varphiFrm$, where $\emptyset
        \in \HypAsg$.
    \end{inparaenum}
\end{enumerate}

\label{thm:hypref}
Let $\varphiFrm$ be an \ADIF formula and $\HypAsg, \HypAsg' \in
\HypAsgSet[\subseteq](\sup{\varphiFrm})$ two hyperteams with ${\HypAsg
\inc[\free{\varphiFrm}] \HypAsg'}$.
Then:
\begin{enumerate}[1)]
  \item\label{thm:hypref(ea)}
    if $\AStr, \HypAsg \cmodels[][\QEA] \varphiFrm$ then $\AStr, \HypAsg'
    \cmodels[][\QEA] \varphiFrm$;
  \item\label{thm:hypref(ae)}
    if $\AStr, \HypAsg' \cmodels[][\QAE] \varphiFrm$ then $\AStr, \HypAsg
    \cmodels[][\QAE] \varphiFrm$.
\end{enumerate}

\label{cor:sensat}
Let $\varphiSnt$ be an \ADIF sentence.
Then, $\varphiSnt$ is $\alpha$-satisfiable \iff $\AStr, \{\!\{\emptyfun\}\!\}
\cmodels[][\alpha] \varphiFrm$, for some $\LSig$-structure $\AStr$.

\label{thm:dbldlt}
For every \ADIF formula $\varphiFrm$ and hyperteam $\HypAsg \in
\HypAsgSet[\subseteq](\sup{\varphiFrm})$, it holds that $\AStr, \HypAsg
\cmodels[][\alpha] \varphiFrm$ \iff $\AStr, \dual{\dual{\HypAsg}}
\cmodels[][\alpha] \varphiFrm$ \iff $\AStr, \dual{\HypAsg}
\cmodels[][\dual{\alpha}] \varphiFrm$.

\label{cor:det}
Let $\varphiFrm$ be an \ADIF formula and $\HypAsg \in
\HypAsgSet[\subseteq](\sup{\varphiFrm})$ a hyperteam.
Then:
\begin{enumerate}[1)]
  \item\label{cor:det(flg)}
    either $\AStr, \HypAsg \cmodels[][\alpha] \varphiFrm$ or $\AStr, \HypAsg
    \cmodels[][\dual{\alpha}] \neg \varphiFrm$;
  \item\label{cor:det(hyp)}
    either $\AStr, \HypAsg \cmodels[][\alpha] \varphiFrm$ or $\AStr,
    \dual{\HypAsg} \cmodels[][\alpha] \neg \varphiFrm$.
\end{enumerate}

\label{thm:blnlawi}
Let $\varphiFrm[1]$, $\varphiFrm[2]$ and $\varphiFrm$ be \ADIF formulae.
Then:
\begin{enumerate}[1)]
  \item\label{thm:blnlawi(neg)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(neg:fbv)}
        $\neg \Ff \equiv \Tt$;
      \hfill
      \item\label{thm:blnlawi(neg:tbv)}
        $\neg \Tt \equiv \Ff$;
      \hfill
      \item\label{thm:blnlawi(neg:inv)}
        $\varphiFrm \equiv \neg \neg \varphiFrm$;
    \end{inparaenum}
  \item\label{thm:blnlawi(conbln)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(conbln:ann)}
        $\varphiFrm \LCon \Ff \equiv \Ff \LCon \varphiFrm \equiv \Ff$;
      \hfill
      \item\label{thm:blnlawi(conbln:idn)}
        $\varphiFrm \LCon \Tt \equiv \Tt \LCon \varphiFrm \equiv \varphiFrm$;
    \end{inparaenum}
  \item\label{thm:blnlawi(disbln)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(disbln:ann)}
        $\varphiFrm \LDis \Tt \equiv \Tt \LDis \varphiFrm \equiv \Tt$;
      \hfill
      \item\label{thm:blnlawi(disbln:idn)}
        $\varphiFrm \LDis \Ff \equiv \Ff \LDis \varphiFrm \equiv \varphiFrm$;
    \end{inparaenum}
  \item\label{thm:blnlawi(com)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(com:con)}
        $\varphiFrm[1] \LCon \varphiFrm[2] \equiv \varphiFrm[2] \LCon
        \varphiFrm[1]$;
      \hfill
      \item\label{thm:blnlawi(com:dis)}
        $\varphiFrm[1] \LDis \varphiFrm[2] \equiv \varphiFrm[2] \LDis
        \varphiFrm[1]$;
    \end{inparaenum}
  \item\label{thm:blnlawi(con)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(con:elm)}
        $\varphiFrm[1] \LCon \varphiFrm[2] \implies \varphiFrm[1]$;
      \hfill
      \item\label{thm:blnlawi(con:ass)}
        $\varphiFrm[1] \LCon (\varphiFrm \LCon \varphiFrm[2]) \equiv
        (\varphiFrm[1] \LCon \varphiFrm) \LCon \varphiFrm[2]$;
    \end{inparaenum}
  \item\label{thm:blnlawi(dis)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(dis:int)}
        $\varphiFrm[1] \implies \varphiFrm[1] \LDis \varphiFrm[2]$;
      \hfill
      \item\label{thm:blnlawi(dis:ass)}
        $\varphiFrm[1] \LDis (\varphiFrm \LDis \varphiFrm[2]) \equiv
        (\varphiFrm[1] \LDis \varphiFrm) \LDis \varphiFrm[2]$;
    \end{inparaenum}
  \item\label{thm:blnlawi(dml)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(dml:con)}
        $\varphiFrm[1] \LCon \varphiFrm[2] \equiv \neg (\neg \varphiFrm[1]
        \LDis \neg \varphiFrm[2])$;
      \hfill
      \item\label{thm:blnlawi(dml:dis)}
        $\varphiFrm[1] \LDis \varphiFrm[2] \equiv \neg (\neg \varphiFrm[1]
        \LCon \neg \varphiFrm[2])$;
    \end{inparaenum}
  \item\label{thm:blnlawi(qnt)}
    \begin{inparaenum}[a)]
      \item\label{thm:blnlawi(qnt:exs)}
        $\LExs[][_{\pm\WSet}] \varElm \ldotp \varphiFrm \equiv \neg
        (\LAll[][_{\pm\WSet}] \varElm \ldotp \neg \varphiFrm)$;
      \hfill
      \item\label{thm:blnlawi(qnt:all)}
        $\LAll[][_{\pm\WSet}] \varElm \ldotp \varphiFrm \equiv \neg
        (\LExs[][_{\pm\WSet}] \varElm \ldotp \neg \varphiFrm)$.
    \end{inparaenum}
\end{enumerate}

\label{lmm:foldlt}
The following equivalences hold, for all \FOL formulae $\varphiFrm$ and
hyperteams $\HypAsg \in \HypAsgSet[\subseteq](\sup{\varphiFrm})$.
\begin{enumerate}[1)]
