    Statements~\ref{lmm:foldlt(ea:org)} and~\ref{lmm:foldlt(ea:dlt)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:foldlt(ea:org)}
        there exists a team $\TeamAsg \!\in\! \HypAsg$ such that $\AStr,
        \asgElm \cmodels[\FOL] \varphiFrm$, for all assignments $\asgElm
        \!\in\! \TeamAsg$;
      \item\label{lmm:foldlt(ea:dlt)}
        for all teams $\TeamAsg \!\in\! \dual{\HypAsg}$, there exists an
        assignment $\asgElm \!\in\! \TeamAsg$ such that $\AStr, \asgElm
        \cmodels[\FOL] \varphiFrm$.
    \end{enumerate}
  \item\label{lmm:foldlt(ae)}
    Statements~\ref{lmm:foldlt(ae:org)} and~\ref{lmm:foldlt(ae:dlt)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:foldlt(ae:org)}
        for all teams $\TeamAsg \!\in\! \HypAsg$, there exists an assignment
        $\asgElm \!\in\! \TeamAsg$ such that $\AStr, \asgElm \cmodels[\FOL]
        \varphiFrm$;\!
      \item\label{lmm:foldlt(ae:dlt)}
        there exists a team $\TeamAsg \!\in\! \dual{\HypAsg}$ such that
        $\AStr, \asgElm \cmodels[\FOL] \varphiFrm$, for all assignments
        $\asgElm \!\in\! \TeamAsg$.
    \end{enumerate}
\end{enumerate}

\label{lmm:folqnt}
The following equivalences hold, for all \FOL formulae $\varphiFrm$, variables
$\varElm \!\in\! \VarSet$, and hyperteams $\HypAsg \!\in\!
\HypAsgSet[\subseteq](\VSet)$ with $\VSet \defeq \sup{\varphiFrm} \setminus \{
\varElm \}$.
\begin{enumerate}[1)]
  \item\label{lmm:folqnt(ea)}
    Statements~\ref{lmm:folqnt(ea:org)} and~\ref{lmm:folqnt(ea:ext)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:folqnt(ea:org)}
        there exists a team $\TeamAsg \in \HypAsg$ such that $\AStr, \asgElm
        \cmodels[\FOL] \LExs \varElm \ldotp \varphiFrm$, for all $\asgElm \in
        \TeamAsg$;
      \item\label{lmm:folqnt(ea:ext)}
        there exists a team $\TeamAsg \in \extFun[\VSet]{\HypAsg, \varElm}$
        such that $\AStr, \asgElm \cmodels[\FOL] \varphiFrm$, for all $\asgElm
        \in \TeamAsg$.
    \end{enumerate}
  \item\label{lmm:folqnt(ae)}
    Statements~\ref{lmm:folqnt(ae:org)} and~\ref{lmm:folqnt(ae:ext)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:folqnt(ae:org)}
        for all teams $\TeamAsg \in \HypAsg$, there exists $\asgElm \in
        \TeamAsg$ such that $\AStr, \asgElm \cmodels[\FOL] \LAll \varElm
        \ldotp \varphiFrm$;
      \item\label{lmm:folqnt(ae:ext)}
        for all teams $\TeamAsg \in \extFun[\VSet]{\HypAsg, \varElm}$, there
        exists $\asgElm \in \TeamAsg$ such that $\AStr, \asgElm \cmodels[\FOL]
        \varphiFrm$.
    \end{enumerate}
\end{enumerate}

\label{lmm:folblncon}
The following equivalences hold, for all \FOL formulae $\varphiFrm[1]$ and
$\varphiFrm[2]$ and hyperteams $\HypAsg \!\in\! \HypAsgSet[\subseteq](\VSet)$
with $\VSet \defeq \sup{\varphiFrm[1]} \cup \sup{\varphiFrm[2]}$.
\begin{enumerate}[1)]
  \item\label{lmm:folblncon(ea)}
    Statements~\ref{lmm:folblncon(ea:org)} and~\ref{lmm:folblncon(ea:par)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:folblncon(ea:org)}
        there exists a team $\TeamAsg \in \HypAsg$ such that $\AStr, \asgElm
        \cmodels[\FOL] \varphiFrm[1] \wedge \varphiFrm[2]$, for all $\asgElm
        \in \TeamAsg$;
      \item\label{lmm:folblncon(ea:par)}
        for each bipartition $(\HypAsg[1], \HypAsg[2]) \in
        \parFun[]{\HypAsg}$, there exist an index $i \in \{ 1, 2 \}$ and a
        team $\TeamAsg \in \HypAsg[i]$ such that $\AStr, \asgElm
        \cmodels[\FOL] \varphiFrm[i]$, for all $\asgElm \in \TeamAsg$.
    \end{enumerate}
  \item\label{lmm:folblncon(ae)}
    Statements~\ref{lmm:folblncon(ae:org)} and~\ref{lmm:folblncon(ae:par)} are
    equivalent:
    \begin{enumerate}[a)]
      \item\label{lmm:folblncon(ae:org)}
        for all teams $\TeamAsg \in \HypAsg$, there exists $\asgElm \in
        \TeamAsg$ such that $\AStr, \asgElm \cmodels[\FOL] \varphiFrm[1] \vee
        \varphiFrm[2]$;
      \item\label{lmm:folblncon(ae:par)}
        there exists a bipartition $(\HypAsg[1], \HypAsg[2]) \in
        \parFun[]{\HypAsg}$ such that, for all indexes $i \in \{ 1, 2 \}$ and
        teams $\TeamAsg \in \HypAsg[i]$, it holds that $\AStr, \asgElm
        \cmodels[\FOL] \varphiFrm[i]$, for some $\asgElm \in \TeamAsg$.
    \end{enumerate}
\end{enumerate}

\label{thm:folsemadq}
For all \FOL formulae $\varphiFrm$ and hyperteams $\HypAsg \in
\HypAsgSet[\subseteq](\sup{\varphiFrm})$, it holds that:
\begin{enumerate}[1)]
  \item\label{thm:folsemadq(ea)}
    $\AStr, \HypAsg \cmodels[][\QEA] \varphiFrm$ \iff there exists a team
    $\TeamAsg \in \HypAsg$ such that, for all assignments $\asgElm \in
    \TeamAsg$, it holds that $\AStr, \asgElm \cmodels[\FOL] \varphiFrm$;
  \item\label{thm:folsemadq(ae)}
    $\AStr, \HypAsg \cmodels[][\QAE] \varphiFrm$ \iff, for all teams $\TeamAsg
    \in \HypAsg$, there exists an assignment $\asgElm \in \TeamAsg$ such that
    $\AStr, \asgElm \cmodels[\FOL] \varphiFrm$.
\end{enumerate}

\label{def:sem(dif)}
The \emph{Hodges' semantic relation} $\AStr, \TeamAsg \cmodels[_{\DIF}][\beta]
\varphiFrm$ for $\dual{\beta}$-\DIF is inductively defined as follows, for
all $\dual{\beta}$-\DIF formulae $\varphiFrm$ and teams $\TeamAsg \subseteq
\AsgSet[\subseteq]( \free{\varphiFrm})$, with $\beta, \dual{\beta} \in \{
\exists, \forall \}$ and $\beta \neq \dual{\beta}$:
\begin{enumerate}[1)]
\item\label{def:sem(dif:a)}
  \begin{enumerate}[a)]
  \item\label{def:sem(dif:rel:a)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall] \RRel(\xVec)$ if, for all
    $\asgElm \in \TeamAsg$, it holds that $\xVec[][\asgElm] \in
    \RRel[][\AStr]$;
  \item\label{def:sem(dif:neg:a)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall] \neg \RRel(\xVec)$ if, for
    all $\asgElm \in \TeamAsg$, it holds that $\xVec[][\asgElm]
    \not\in \RRel[][\AStr]$;
  \item\label{def:sem(dif:con:a)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall] \varphiFrm[1] \LCon
    \varphiFrm[2]$ if $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall]
    \varphiFrm[1]$ and $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall]
    \varphiFrm[2]$;
  \item\label{def:sem(dif:dis:a)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall] \varphiFrm[1] \LDis[][]
    \varphiFrm[2]$ if $\AStr, \TeamAsg[1] \cmodels[_{\DIF}][\forall]
    \varphiFrm[1]$ and $\AStr, \TeamAsg[2] \cmodels[_{\DIF}][\forall]
    \varphiFrm[2]$, for some bipartition $(\TeamAsg[1], \TeamAsg[2]) \in
    \parFun[]{\TeamAsg}$;
  \item\label{def:sem(dif:exs:a)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall] \LExs[][_{\pm\WSet}] \varElm
    \ldotp \varphiFrm[]$ if $\AStr, \extFun{\TeamAsg, \FFun, \varElm}
    \cmodels[_{\DIF}][\forall] \varphiFrm[]$, for some $\FFun \in
    \FncSet[\denot{\pm\WSet}]{}$;
  \item\label{def:sem(dif:all:a)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\forall] \LAll[][-\emptyset] \varElm
    \ldotp \varphiFrm[]$ if $\AStr, \cylFun{\TeamAsg, \varElm}
    \cmodels[_{\DIF}][\forall] \varphiFrm[]$;
  \end{enumerate}
\item\label{def:sem(dif:e)}
  \begin{enumerate}[a)]
  \item\label{def:sem(dif:rel:e)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists] \RRel(\xVec)$ if there
    exists $\asgElm \in \TeamAsg$ such that $\xVec[][\asgElm] \in
    \RRel[][\AStr]$;
  \item\label{def:sem(dif:neg:e)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists] \neg \RRel(\xVec)$ if there
    exists $\asgElm \in \TeamAsg$ such that $\xVec[][\asgElm] \notin
    \RRel[][\AStr]$;
  \item\label{def:sem(dif:con:e)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists] \varphiFrm[1] \LCon[][]
    \varphiFrm[2]$ if $\AStr, \TeamAsg[1] \cmodels[_{\DIF}][\exists]
    \varphiFrm[1]$ or $\AStr, \TeamAsg[2] \cmodels[_{\DIF}][\exists]
    \varphiFrm[2]$, for all bipartitions $(\TeamAsg[1], \TeamAsg[2]) \in
    \parFun[]{\TeamAsg}$;
  \item\label{def:sem(dif:dis:e)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists] \varphiFrm[1] \LDis[][]
    \varphiFrm[2]$ if $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists]
    \varphiFrm[1]$ or $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists]
    \varphiFrm[2]$;
  \item\label{def:sem(dif:exs:e)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists] \LExs[][-\emptyset] \varElm
    \ldotp \varphiFrm[]$ if $\AStr, \cylFun{\TeamAsg, \varElm}
    \cmodels[_{\DIF}][\exists] \varphiFrm[]$;
  \item\label{def:sem(dif:all:e)}
    $\AStr, \TeamAsg \cmodels[_{\DIF}][\exists] \LAll[][_{\pm\WSet}]
    \varElm \ldotp \varphiFrm[]$ if $\AStr, \extFun[]{\TeamAsg, \FFun,
    \varElm} \cmodels[_{\DIF}][\exists] \varphiFrm[]$, for all $\FFun \in
    \FncSet[\denot{\pm\WSet}]{}$.
  \end{enumerate}
\end{enumerate}

\label{lmm:teapar}
Let $\HypAsg \in \HypAsgSet$ be a hyperteam.
Then:
\begin{enumerate}[1)]
\item\label{lmm:teapar(hyp)}
  for all hyperteam bipartitions $(\HypAsg[1], \HypAsg[2]) \in
  \parFun[]{\dual{\HypAsg}}$ and teams $\YSet[1] \in \dual{\HypAsg[1]}$ and
  $\YSet[2] \in \dual{\HypAsg[2]}$, there exists a team $\TeamAsg \in
  \HypAsg$ such that $\TeamAsg \subseteq \YSet[1] \cup \YSet[2]$;
\item\label{lmm:teapar(tea)}
  for all teams $\TeamAsg \in \HypAsg$ and team bipartitions $(\TeamAsg[1],
  \TeamAsg[2]) \in \parFun[]{\TeamAsg}$, there exist a hyperteam bipartition
  $(\HypAsg[1], \HypAsg[2]) \in \parFun[]{\dual{\HypAsg}}$ and two teams
  $\YSet[1] \in \dual{\HypAsg[1]}$ and $\YSet[2] \in \dual{\HypAsg[2]}$ such
  that $\YSet[1] \subseteq \TeamAsg[1]$ and $\YSet[2] \subseteq \TeamAsg[2]$.
\end{enumerate}

\label{thm:difsemadq}
For all $\exists/\forall$-\DIF formulae
$\varphiFrm[][_{\exists}]/\varphiFrm[][_{\forall}]$ and hyperteams $\HypAsg
\in \HypAsgSet[\subseteq](\sup{}(
\varphiFrm[][_{\exists}]/\varphiFrm[][_{\forall}]\, ))$, it holds that:
\begin{enumerate}[1)]
  \item\label{thm:difsemadq(ea)}
    $\AStr, \HypAsg \cmodels[][\QEA]\! \varphiFrm[][_{\exists}]$ \iff there
    exists a team $\TeamAsg \in \HypAsg$ such that $\AStr, \TeamAsg
    \cmodels[_{\DIF}][\forall] \varphiFrm[][_{\exists}]$;
  \item\label{thm:difsemadq(ae)}
    $\AStr, \HypAsg \cmodels[][\QAE]\! \varphiFrm[][_{\forall}]$ \iff, for all
    teams $\TeamAsg \in \HypAsg$, it holds that $\AStr, \TeamAsg
    \cmodels[_{\DIF}][\exists] \varphiFrm[][_{\forall}]$.
\end{enumerate}

\label{lmm:extint}
The following four equivalences hold true, for all hyperteams $\HypAsg \in
\HypAsgSet(\VSet)$ over $\VSet \subseteq \VarSet$, properties $\PsiSet
\subseteq \AsgSet(\VSet \cup \{ \varElm \})$ over $\VSet \cup \{ \varElm \}$
with $\varElm \in \VarSet \setminus \VSet$, sets of variables $\WSet
\subseteq \VarSet$, and quantifier symbols $\Qnt \in \{ \LExs, \LAll \}$.
\begin{enumerate}[1)]
  \item\label{lmm:extint(inccoh)}
    Statements~\ref{lmm:extint(inccoh:org)} and~\ref{lmm:extint(inccoh:int)}
    are equivalent, whenever $\Qnt$ is $\alpha$-coherent:
    \begin{enumerate}[a)]
      \item\label{lmm:extint(inccoh:org)}
        there exists $\TeamAsg' \in \extFun[\alpha]{\HypAsg,
        \Qnt[][_{\pm\WSet}] \varElm}$ such that $\TeamAsg' \subseteq \PsiSet$;
      \item\label{lmm:extint(inccoh:int)}
        there exist $\FFun \in \FncSet[\denot{\pm\WSet}]{}$ and $\TeamAsg \in \HypAsg$
        such that $\extFun{\TeamAsg, \FFun, \varElm} \subseteq \PsiSet$.
    \end{enumerate}
  \item\label{lmm:extint(intcoh)}
    Statements~\ref{lmm:extint(intcoh:org)} and~\ref{lmm:extint(intcoh:int)}
    are equivalent, whenever $\Qnt$ is $\alpha$-coherent:
    \begin{enumerate}[a)]
      \item\label{lmm:extint(intcoh:org)}
        for all $\TeamAsg' \in \extFun[\alpha]{\HypAsg, \Qnt[][_{\pm\WSet}]
        \varElm}$, it holds that $\TeamAsg' \cap \PsiSet \neq \emptyset$;
      \item\label{lmm:extint(intcoh:int)}
        for all $\FFun \in \FncSet[\denot{\pm\WSet}]{}$ and $\TeamAsg \in \HypAsg$, it
        holds that $\extFun{\TeamAsg, \FFun, \varElm} \cap \PsiSet \neq
        \emptyset$.
    \end{enumerate}
  \item\label{lmm:extint(incnch)}
    Statements~\ref{lmm:extint(incnch:org)} and~\ref{lmm:extint(incnch:int)}
    are equivalent, whenever $\Qnt$ is $\dual{\alpha}$-coherent:
    \begin{enumerate}[a)]
      \item\label{lmm:extint(incnch:org)}
        there exists $\TeamAsg' \in \extFun[\alpha]{\HypAsg,
        \Qnt[][_{\pm\WSet}] \varElm}$ such that $\TeamAsg' \subseteq \PsiSet$;
      \item\label{lmm:extint(incnch:int)}
        for all $\FFun \in \FncSet[\denot{\pm\WSet}]{}$, it holds that
        $\extFun{\TeamAsg, \FFun, \varElm} \subseteq \PsiSet$, for some
        $\TeamAsg \in \HypAsg$.
    \end{enumerate}
  \item\label{lmm:extint(intnch)}
    Statements~\ref{lmm:extint(intnch:org)} and~\ref{lmm:extint(intnch:int)}
    are equivalent, whenever $\Qnt$ is $\dual{\alpha}$-coherent:
    \begin{enumerate}[a)]
      \item\label{lmm:extint(intnch:org)}
        for all $\TeamAsg' \in \extFun[\alpha]{\HypAsg, \Qnt[][_{\pm\WSet}]
        \varElm}$, it holds that $\TeamAsg' \cap \PsiSet \neq \emptyset$;
      \item\label{lmm:extint(intnch:int)}
        there is $\FFun \in \FncSet[\denot{\pm\WSet}]{}$ such that $\extFun{\TeamAsg,
        \FFun, \varElm} \cap \PsiSet \neq \emptyset$, for all $\TeamAsg \in
        \HypAsg$.
    \end{enumerate}
\end{enumerate}

