\label{cns:semarn}
For a finite structure $\AStr$ and a \pnf \ADIF sentence $\varphiSnt \!=\!
\qntElm \psiFrm$, with $\psi \!\in\! \FOL$, the \emph{independence arena}
$\ArenaName[\varphiSnt][\AStr] =\! \tuplel {\PosSet} {\PPosSet}
{\OPosSet,}\!\!\! \allowbreak \tupler {\iposElm} {\MovRel}$ is defined as
prescribed in the following:
\begin{enumerate}[1)]
  \item\label{cns:semarn(pos)}
    the set of positions $\PosSet \subset \psf{\varphiSnt} \times \AsgSet
    \times \{ \PhsISym, \PhsIISym \}$ contains those triples $(\phiFrm,
    \asgElm, \blacklozenge)$ of a prefix subformula $\phiFrm \in
    \psf{\varphiSnt}$ of $\varphiSnt$, an assignment $\asgElm \in \AsgSet$,
    and a phase flag $\blacklozenge \in \{ \PhsISym, \PhsIISym \}$ such that
    $\asgElm \in \AsgSet(\free{\phiFrm})$, if $\blacklozenge = \PhsISym$, and
    $\asgElm \in \AsgSet(\free{\psiFrm})$, otherwise;
  \item\label{cns:semarn(eap)}
    the set $\PPosSet$ of Eloise's (\resp, $\OPosSet$ of Abelard's) positions
    contains the triples of the form $(\LExs[][_{\pm\WSet}] \!\varElm\!
    \ldotp\! \phiFrm'\!\!, \asgElm, \blacklozenge)$ or $(\psiFrm, \asgElm,
    \PhsISym)$ (\resp, $(\LAll[][_{\pm\WSet}] \!\varElm\! \ldotp\!
    \phiFrm'\!\!, \asgElm, \blacklozenge)$);
  \item\label{cns:semarn(ini)}
    the initial position $\iposElm \defeq (\varphiSnt, \emptyfun, \PhsISym)$
    contains the original sentence $\varphiSnt$ associated with the empty
    assignment $\emptyfun$ and the phase flag $\PhsISym$;
  \item\label{cns:semarn(mov)}
    the move relation $\MovRel \subseteq \PosSet \times \PosSet$ contains
    exactly those pairs of positions $(\posElm[1], \posElm[2]) \in \PosSet
    \times \PosSet$ satisfying one of the conditions below:
    \begin{enumerate}[a)]
      \item\label{cns:semarn(mov:noc)}
        $\posElm[1] = (\Qnt[][_{\pm\WSet}] \varElm \ldotp \phiFrm', \asgElm,
        \blacklozenge)$ and $\posElm[2] = (\phiFrm', \asgElm, \blacklozenge)$,
        with $\varElm \not\in \free{\phiFrm'}$;
      \item\label{cns:semarn(mov:chc)}
        $\posElm[1] = (\Qnt[][_{\pm\WSet}] \varElm \ldotp \phiFrm'\!, \asgElm,
        \PhsISym)$ and $\posElm[2] = (\phiFrm'\!, {\asgElm}[\varElm
        \!\mapsto\! \aElm], \PhsISym)$, for some $\aElm \!\in\! \ASet$;
      \item\label{cns:semarn(mov:swp)}
        $\posElm[1] = (\psiFrm, \asgElm, \PhsISym)$ and $\posElm[2] =
        (\varphiSnt, \asgElm, \PhsIISym)$;
      \item\label{cns:semarn(mov:cnf)}
        $\posElm[1] = (\Qnt[][_{\pm\WSet}] \varElm \ldotp \phiFrm', \asgElm,
        \PhsIISym)$ and $\posElm[2] = (\phiFrm', \asgElm, \PhsIISym)$;
      \item\label{cns:semarn(mov:chl)}
        $\posElm[1] = (\Qnt[][_{\pm\WSet}] \varElm \ldotp \phiFrm'\!, \asgElm,
        \PhsIISym)$ and $\posElm[2] \!=\! (\phiFrm'\!, \asgElm'[\varElm
        \!\mapsto\! \aElm], \PhsISym)$, for some $\aElm \!\in\! \ASet$ with
        $\aElm \neq \asgElm(\varElm)$, where $\asgElm' \defeq \asgElm \!\rst
        \free{\Qnt[][_{\pm\WSet}] \varElm \ldotp \phiFrm'}$.
    \end{enumerate}
\end{enumerate}

